#!/usr/bin/env python3
"""Build the reference-style SMPL-H people1 viewer from one current replay."""
from __future__ import annotations
import argparse, base64, gzip, inspect, json, pickle
from pathlib import Path
import numpy as np

def enc(a): return base64.b64encode(gzip.compress(np.ascontiguousarray(a).tobytes(), 6)).decode()
def main():
    p=argparse.ArgumentParser(); p.add_argument('--result',type=Path,required=True); p.add_argument('--scene',type=Path,required=True); p.add_argument('--smplh',type=Path,required=True); p.add_argument('--output',type=Path,required=True); a=p.parse_args()
    z=np.load(a.result); V=z['vertices'].astype(np.float32); F=z['faces'].astype(np.uint32); C=z['predicted_coco'].astype(np.float32); T=z['raw_triangulated_points'].astype(np.float32)/1000; A=z['body_accepted'].astype(np.uint8)
    HL=z['hand_points_left'].astype(np.float32); HR=z['hand_points_right'].astype(np.float32)
    S=np.load(a.scene/'scene_transforms.npz'); R=S['rotation_ground_from_left'].astype(np.float32); tr=S['translation_ground_from_left_mm'].astype(np.float32)/1000
