    md.setdefault('hands_componentsl',np.eye(45,dtype=np.float32)); md.setdefault('hands_componentsr',np.eye(45,dtype=np.float32)); md.setdefault('hands_meanl',np.zeros(45,dtype=np.float32)); md.setdefault('hands_meanr',np.zeros(45,dtype=np.float32))
    with np.load(a.result) as q: beta=q['betas']; root=q['global_orient']; body=q['body_pose']; lh=q['left_hand_pose']; rh=q['right_hand_pose']; trans=q['transl']
    m=smplx.SMPLH(str(a.smplh),data_struct=Struct(**md),gender='male',use_pca=False,flat_hand_mean=True,batch_size=len(V))
    with torch.no_grad(): J=m(betas=torch.tensor(np.repeat(beta,len(V),axis=0)),global_orient=torch.tensor(root),body_pose=torch.tensor(body),left_hand_pose=torch.tensor(lh),right_hand_pose=torch.tensor(rh),transl=torch.tensor(trans),return_verts=False).joints.numpy().astype(np.float32)
    J=xf(J)
    walker=json.loads((a.scene/'static_walker_model.json').read_text(encoding='utf8')); names=list(walker['nodes_walker_mm']); W=np.asarray([walker['nodes_walker_mm'][n] for n in names],np.float32)/1000; Rc=np.asarray(walker['rotation_left_camera_from_walker'],np.float32); tc=np.asarray(walker['translation_left_camera_from_walker_mm'],np.float32)/1000; W=W@Rc.T+tc; W=np.einsum('nij,vj->nvi',R,W)+tr[:,None,:]
    Cams=np.zeros((len(V),2,3),np.float32); Cams[:,0]=tr; c1=np.asarray(walker['camera_centers_left_camera_mm']['right'],np.float32)/1000; Cams[:,1]=np.einsum('nij,j->ni',R,c1)+tr
    stages=[];poses=[]
