    payload={'v':enc(V),'f':enc(F),'c':enc(C),'t':enc(T),'tf':enc(finite_T),'j':enc(J),'hl':enc(HL),'hr':enc(HR),'w':enc(W),'cam':enc(Cams),'a':A.tolist(),'N':len(V),'NV':V.shape[1],'NJ':J.shape[1],'stages':stages,'poses':poses,'wn':names,'we':[[names.index(x),names.index(y)] for x,y in walker['edges']]}
    page=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>people1 SMPL-H 参考式可视化</title><style>:root{font-family:Inter,"Microsoft YaHei",sans-serif;color:#17212b;background:#edf2f5}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-rows:auto 1fr auto}.top,.timeline{background:#fff;padding:12px 18px;border-bottom:1px solid #d5dde2}.top{display:flex;justify-content:space-between}.top h1{margin:0;font-size:20px;font-weight:500}.top p{margin:4px 0;color:#65727c;font-size:13px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;min-height:0}.viewport{position:relative;min-height:560px;background:#f5f8fa}.viewport canvas{width:100%;height:100%;display:block}.help{position:absolute;left:12px;bottom:10px;padding:5px 8px;background:#ffffffe0;color:#5b6871;font-size:12px}.side{padding:14px 16px;background:#fff;border-left:1px solid #d5dde2;overflow:auto}.side section+section{margin-top:16px;padding-top:14px;border-top:1px solid #e3e8eb}.side h2{margin:0 0 9px;font-size:14px}.metrics{display:grid;gap:7px}.metrics div{display:flex;justify-content:space-between;gap:8px}.metrics dt{color:#65727c}.metrics dd{margin:0;text-align:right}.checks{display:grid;gap:8px}.checks label{display:flex;gap:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}button,select{border:1px solid #b8c3ca;border-radius:7px;background:#fff;min-height:34px;padding:6px 9px}button.play{background:#176b7e;color:#fff}.timeline{display:grid;grid-template-columns:auto auto minmax(120px,1fr) auto auto;gap:9px;align-items:center;border-top:1px solid #d5dde2;border-bottom:0}#slider{width:100%}.boundary{color:#5e6c75;font-size:13px;line-height:1.5}</style></head><body><main class="app"><header class="top"><div><h1>people1 · SMPL-H + WiLoR</h1><p>6,890 顶点 / 13,776 三角面 · 当前场景重放 · 无显示平滑</p></div><span id="frame">1 / 448</span></header><section class="layout"><div id="viewport" class="viewport"><div class="help">左键旋转 · 右键平移 · 滚轮缩放</div><canvas id="canvas"></canvas></div><aside class="side"><section><h2>当前帧</h2><dl class="metrics"><div><dt>Stage</dt><dd id="stage">—</dd></div><div><dt>地面变换</dt><dd id="pose">—</dd></div><div><dt>严格 accepted</dt><dd id="accepted">—</dd></div></dl></section><section><h2>视角</h2><div class="grid"><button data-view="r">推荐视角</button><button data-view="f">正视</button><button data-view="s">侧视</button><button data-view="t">俯视</button></div></section><section><h2>显示</h2><div class="checks"><label><input id="mesh" type="checkbox" checked> SMPL-H 完整表面</label><label><input id="model" type="checkbox" checked> 模型 COCO-17</label><label><input id="tri" type="checkbox" checked> 原始三角化点</label><label><input id="links" type="checkbox" checked> COCO 骨架</label><label><input id="walker" type="checkbox" checked> 实体助步器</label><label><input id="cams" type="checkbox" checked> 双相机光心/轨迹</label><label><input id="hands" type="checkbox" checked> SMPL-H 52内部关节 + 双手21点</label></div></section><section><h2>证据边界</h2><p class="boundary">手部点来自 WiLoR 的 MANO 模型投影，当前页面显示保存的 SMPL-H 参数和当前地面重放。它们是工程候选，不代表独立二维真值、真实三维精度或握持/承重。</p></section></aside></section><footer class="timeline"><button id="play" class="play">播放</button><label for="slider">帧</label><input id="slider" type="range" min="0" max="447" value="0"><select id="rate"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></footer></main><script id="data" type="application/json">DATA</script><script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js"}}</script><script type="module">import*as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';import{OrbitControls}from 'https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js';const d=JSON.parse(document.querySelector('#data').textContent),ug=async s=>new Float32Array(await new Response(new Blob([Uint8Array.from(atob(s),c=>c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer()),[V,F,C,T,TF,J,HL,HR,W,Cam]=await Promise.all([ug(d.v),new Uint32Array(await new Response(new Blob([Uint8Array.from(atob(d.f),c=>c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer()),ug(d.c),ug(d.t),ug(d.tf),ug(d.j),ug(d.hl),ug(d.hr),ug(d.w),ug(d.cam)]);const N=d.N,NV=d.NV,NJ=d.NJ,view=document.querySelector('#viewport'),ren=new THREE.WebGLRenderer({canvas:document.querySelector('#canvas'),antialias:true});ren.setPixelRatio(Math.min(devicePixelRatio,2));const sc=new THREE.Scene(),cam=new THREE.PerspectiveCamera(42,1,.01,20),ctl=new OrbitControls(cam,ren.domElement);sc.background=new THREE.Color(0xf5f8fa);cam.up.set(0,0,1);ctl.enableDamping=true;ctl.screenSpacePanning=true;sc.add(new THREE.HemisphereLight(0xffffff,0x777777,2.2));const dl=new THREE.DirectionalLight(0xffffff,2);dl.position.set(2,4,3);sc.add(dl);const G={ground:new THREE.Group(),mesh:new THREE.Group(),model:new THREE.Group(),tri:new THREE.Group(),links:new THREE.Group(),walker:new THREE.Group(),cams:new THREE.Group(),hands:new THREE.Group()};Object.values(G).forEach(x=>sc.add(x));G.ground.add(new THREE.Mesh(new THREE.PlaneGeometry(8,8),new THREE.MeshStandardMaterial({color:0x718279,side:THREE.DoubleSide})),new THREE.GridHelper(8,16,0xd8dedb,0xaeb9b3),new THREE.AxesHelper(1.2));const geo=new THREE.BufferGeometry(),pos=new Float32Array(NV*3);geo.setAttribute('position',new THREE.BufferAttribute(pos,3));geo.setIndex(new THREE.BufferAttribute(F,1));G.mesh.add(new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:0xc8896b,transparent:true,opacity:.48,side:THREE.DoubleSide,depthWrite:false})));const pgeo=new THREE.BufferGeometry(),pp=new Float32Array(17*3);pgeo.setAttribute('position',new THREE.BufferAttribute(pp,3));G.model.add(new THREE.Points(pgeo,new THREE.PointsMaterial({color:0x0b6e4f,size:.035})));const tgeo=new THREE.BufferGeometry(),tp=new Float32Array(17*3),tc=new Float32Array(17*3);tgeo.setAttribute('position',new THREE.BufferAttribute(tp,3));tgeo.setAttribute('color',new THREE.BufferAttribute(tc,3));G.tri.add(new THREE.Points(tgeo,new THREE.PointsMaterial({vertexColors:true,size:.028})));const E=[[5,6],[5,7],[7,9],[6,8],[8,10],[5,11],[6,12],[11,12],[11,13],[13,15],[12,14],[14,16],[0,1],[0,2],[1,3],[2,4]],lg=new THREE.BufferGeometry(),lp=new Float32Array(E.length*6);lg.setAttribute('position',new THREE.BufferAttribute(lp,3));G.links.add(new THREE.LineSegments(lg,new THREE.LineBasicMaterial({color:0x17212b})));const jg=new THREE.BufferGeometry(),jp=new Float32Array(42*3);jg.setAttribute('position',new THREE.BufferAttribute(jp,3));G.hands.add(new THREE.Points(jg,new THREE.PointsMaterial({color:0x8b2be2,size:.032})));const bg=new THREE.BufferGeometry(),bp=new Float32Array(52*3);bg.setAttribute('position',new THREE.BufferAttribute(bp,3));G.hands.add(new THREE.Points(bg,new THREE.PointsMaterial({color:0x34495e,size:.022})));const he=Array.from({length:5},(_,f)=>{const k=1+4*f;return [[0,k],[k,k+1],[k+1,k+2],[k+2,k+3]]}).flat(),hg=new THREE.BufferGeometry(),hp=new Float32Array(40*6);hg.setAttribute('position',new THREE.BufferAttribute(hp,3));G.hands.add(new THREE.LineSegments(hg,new THREE.LineBasicMaterial({color:0x6a1b9a}))); const wg=new THREE.Group();G.walker.add(wg);for(const e of d.we){const line=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:0x176b7e}));line.geometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(6),3));wg.add(line)}const cg=new THREE.Group();G.cams.add(cg);const camlines=[0,1].map(i=>{const l=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:i?0x7b3f98:0xaa4a18}));l.geometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(N*3),3));cg.add(l);return l});let fi=0,playing=false,last=0;function v(a,o){return[a[o],a[o+1],a[o+2]]}function set(n){fi=n;pos.set(V.subarray(n*NV*3,(n+1)*NV*3));geo.attributes.position.needsUpdate=true;geo.computeVertexNormals();pp.set(C.subarray(n*51,n*51+51));pgeo.attributes.position.needsUpdate=true;tp.set(T.subarray(n*51,n*51+51));for(let i=0;i<17;i++){const ok=TF[n*17+i]>0;tc.set(ok?[0.78,0.10,0.10]:[1.0,0.55,0.05],i*3)}tgeo.attributes.position.needsUpdate=true;tgeo.attributes.color.needsUpdate=true;for(let i=0;i<E.length;i++){lp.set([...v(T,n*51+E[i][0]*3),...v(T,n*51+E[i][1]*3)],i*6)}lg.attributes.position.needsUpdate=true;for(let i=0;i<21;i++)jp.set(v(HL,n*63+i*3),i*3);for(let i=0;i<21;i++)jp.set(v(HR,n*63+i*3), (21+i)*3);jg.attributes.position.needsUpdate=true;for(let i=0;i<52;i++)bp.set(v(J,n*NJ*3+i*3),i*3);bg.attributes.position.needsUpdate=true;for(let i=0;i<he.length;i++){const[a,b]=he[i],q=new Float32Array([...v(jp,a*3),...v(jp,b*3)]);hp.set(q,i*6);const[a2,b2]=[a+21,b+21];hp.set(new Float32Array([...v(jp,a2*3),...v(jp,b2*3)]), (i+he.length)*6)}hg.attributes.position.needsUpdate=true;for(let i=0;i<d.we.length;i++){const[a,b]=d.we[i],q=new Float32Array([...v(W,n*d.wn.length*3+a*3),...v(W,n*d.wn.length*3+b*3)]);wg.children[i].geometry.attributes.position.array.set(q);wg.children[i].geometry.attributes.position.needsUpdate=true}for(let s=0;s<2;s++){const q=new Float32Array(N*3);for(let i=0;i<N;i++)q.set(v(Cam,i*6+s*3),i*3);camlines[s].geometry.attributes.position.array.set(q);camlines[s].geometry.attributes.position.needsUpdate=true}document.querySelector('#frame').textContent=`${n+1} / ${N}`;document.querySelector('#stage').textContent=d.stages[n];document.querySelector('#pose').textContent=d.poses[n];document.querySelector('#accepted').textContent=d.a[n].filter(Boolean).length;document.querySelector('#slider').value=n}function resize(){const w=view.clientWidth,h=view.clientHeight;ren.setSize(w,h,false);cam.aspect=w/Math.max(h,1);cam.updateProjectionMatrix()}const views={r:[2,-3,1.7],f:[0,-3,1.2],s:[3,0,1.2],t:[0,0,5]};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{cam.position.set(...views[b.dataset.view]);ctl.target.set(0,0,1);ctl.update()});document.querySelectorAll('.checks input').forEach(x=>x.onchange=()=>G[x.id].visible=x.checked);document.querySelector('#slider').oninput=e=>{playing=false;set(+e.target.value)};document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'暂停':'播放'};function loop(t){if(playing&&t-last>33/parseFloat(rate.value)){set((fi+1)%N);last=t}ctl.update();ren.render(sc,cam);requestAnimationFrame(loop)}onresize=resize;resize();cam.position.set(...views.r);ctl.target.set(0,0,1);ctl.update();set(0);loop(0)</script></body></html>'''
    a.output.parent.mkdir(parents=True,exist_ok=True); a.output.write_text(page.replace('DATA',json.dumps(payload,separators=(',',':'))),encoding='utf8'); print(a.output.resolve())
